CREATE TABLE IF NOT EXISTS "Vehicle" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"vehicleNumber" TEXT NOT NULL,"registrationNumber" TEXT NOT NULL,"type" TEXT NOT NULL,"capacity" INTEGER NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"driverId" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("tenantId","schoolId","vehicleNumber"),UNIQUE("tenantId","schoolId","registrationNumber"));
CREATE TABLE IF NOT EXISTS "TransportDriver" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"name" TEXT NOT NULL,"phone" TEXT,"licenseNumber" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("tenantId","schoolId","licenseNumber"));
CREATE TABLE IF NOT EXISTS "TransportRoute" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"code" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,UNIQUE("tenantId","schoolId","code"));
CREATE TABLE IF NOT EXISTS "TransportStop" ("id" UUID PRIMARY KEY,"routeId" UUID NOT NULL REFERENCES "TransportRoute"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"sequence" INTEGER NOT NULL,"pickupTime" TEXT,UNIQUE("routeId","sequence"));
CREATE TABLE IF NOT EXISTS "TransportTrip" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"routeId" UUID NOT NULL REFERENCES "TransportRoute"("id") ON DELETE CASCADE,"vehicleId" TEXT,"driverId" TEXT,"scheduledAt" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL DEFAULT 'SCHEDULED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "VehicleInspection" ("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL,"schoolId" UUID NOT NULL,"vehicleId" UUID NOT NULL REFERENCES "Vehicle"("id") ON DELETE CASCADE,"passed" BOOLEAN NOT NULL DEFAULT false,"inspectedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"notes" TEXT);
